@pytest.mark.parametrize("auth_scenario", ["valid", "invalid", "missing"], ids=["valid_auth", "invalid_auth", "missing_auth"])
def test_create_user_auth(api_client, api_host, auth_scenario, scenario_case):
    """
    Test the authentication scenarios for the /user endpoint.
    This test covers valid, invalid, and missing authentication tokens.
    """
    user_data = {
        "id": scenario_case.get("id"),
        "username": scenario_case.get("username"),
        "firstName": scenario_case.get("firstName"),
        "lastName": scenario_case.get("lastName"),
        "email": scenario_case.get("email"),
        "password": scenario_case.get("password"),
        "phone": scenario_case.get("phone"),
        "userStatus": scenario_case.get("userStatus")
    }

    # Remove keys with None values
    user_data = {k: v for k, v in user_data.items() if v is not None}

    # Validate request data against the OpenAPI spec
    validator.validate_json(user_data, "user")

    headers = {}
    if auth_scenario == "valid":
        headers["Authorization"] = f"Bearer {api_client.session.headers.get('Authorization')}"
    elif auth_scenario == "invalid":
        headers["Authorization"] = "Bearer invalid_token"

    # Send POST request
    response = api_client.post("/user", data=user_data, headers=headers)

    # Validate the response schema
    validate_result = validator.validate_schema_by_response("/user", "post", str(response.status_code), response)
    assert validate_result["valid"], f"Response validation failed: {validate_result.get('message', '')}"

    # Assert response status code for auth scenarios
    if auth_scenario == "valid":
        assert response.status_code == scenario_case["statusCode"], f"Expected status code {scenario_case['statusCode']}, got {response.status_code}"
    elif auth_scenario == "invalid":
        assert response.status_code in [401, 403], f"Expected 401 or 403 for invalid auth, got {response.status_code}"
    elif auth_scenario == "missing":
        assert response.status_code == 401, f"Expected 401 for missing auth, got {response.status_code}"
